/* UI assets served by the existing Product Insights Scrappers Worker. */
export const managementHtml = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"color-scheme\" content=\"dark\">\n<title>Product Insights | Working Prototype — Decision Workspace</title>\n<link rel=\"stylesheet\" href=\"/insights/styles.css\">\n<script src=\"/insights/app.js\" defer></script>\n</head>\n<body>\n<a class=\"skip\" href=\"#outcome\">Skip to outcomes</a>\n<header class=\"topbar\">\n  <div class=\"wrap top-inner\">\n    <a class=\"brand\" href=\"/demo\" aria-label=\"Product Insights home\">\n      <div class=\"logo\">PI<span></span></div>\n      <div><strong>PRODUCT INSIGHTS</strong><small>INSIDEJOB / PROTOTYPE</small></div>\n    </a>\n    <nav class=\"topnav\" aria-label=\"Sections\"><a href=\"#outcome\" class=\"nav-current\">Outcomes</a><a href=\"#live\">Live website + AI</a><a href=\"#how\">How it works</a><a href=\"#limitations\">What is verified</a></nav>\n    <div class=\"health-pill\" id=\"health-pill\"><i></i><span>Checking prototype</span></div>\n  </div>\n</header>\n<main class=\"wrap\">\n  <section class=\"hero\" aria-labelledby=\"hero-title\">\n    <div class=\"hero-copy\">\n      <div class=\"eyebrow\"><span class=\"eyebrow-rule\"></span> ENGINEERING INTELLIGENCE / DEMO V0.2 <span class=\"tag\">WORKING PROTOTYPE</span></div>\n      <h1 id=\"hero-title\">From product information<br>to <em>manufacturing possibilities.</em></h1>\n      <p>We can detect how websites deliver information, extract evidence, and explore possible manufacturing processes and supplier capabilities. This demo shows what's working—and where human verification is still needed.</p>\n      <div class=\"hero-actions\"><a href=\"#outcome\" class=\"btn-primary\">Explore pilot outcomes <span aria-hidden=\"true\">↗</span></a><a href=\"#live\" class=\"btn-secondary\">Try live website analysis</a></div>\n      <p class=\"hero-foot\"><span class=\"mint-dot\"></span> Patricio’s inference uses human-authored rules. Cloudflare AI is added only for optional, unverified fact suggestions.</p>\n    </div>\n    <div class=\"hero-journey\">\n      <div class=\"journey-header\"><span>FROM INPUT TO OUTCOME</span><span class=\"journey-caption\">Two independently verified prototypes</span></div>\n      <div class=\"journey-step\"><span class=\"journey-index\">01</span><div><b>Investigate the website</b><small>Our live Pattern Systems + S01 pipeline</small></div><span class=\"journey-state good\">LIVE</span></div>\n      <div class=\"journey-line\"></div>\n      <div class=\"journey-step\"><span class=\"journey-index\">02</span><div><b>Structure product facts</b><small>Evidence review + human-approved roles</small></div><span class=\"journey-state pending\">GAP</span></div>\n      <div class=\"journey-line\"></div>\n      <div class=\"journey-step\"><span class=\"journey-index\">03</span><div><b>Propose manufacturing steps</b><small>Patricio's deterministic Busch pilot</small></div><span class=\"journey-state good\">PILOT</span></div>\n      <div class=\"journey-line\"></div>\n      <div class=\"journey-step\"><span class=\"journey-index\">04</span><div><b>Compare process capabilities</b><small>Ten synthetic example suppliers</small></div><span class=\"journey-state good\">PILOT</span></div>\n    </div>\n  </section>\n\n  <div class=\"notice\" id=\"limitations\"><span class=\"notice-icon\">!</span><p><strong>Demonstration, not a supplier recommendation.</strong> The Busch product facts have not been independently verified, and every supplier shown below is synthetic. Matching process labels does not prove full manufacturing capability, OEM demand, or commercial opportunity.</p><button type=\"button\" data-panel=\"limitations\" class=\"notice-link\">Review limitations <span>↗</span></button></div>\n\n  <section id=\"outcome\" class=\"section outcomes\">\n    <div class=\"section-heading\"><div><p class=\"section-id\">01 / DEMONSTRATION OUTCOME</p><h2>What the system can show today</h2><p class=\"subtitle\">An actual snapshot from Patricio’s deterministic Python handoff. Presented as a process-compatibility example—not live qualified suppliers.</p></div><button class=\"outline-button\" type=\"button\" data-panel=\"method\">View the complete approach <span>↗</span></button></div>\n    <div class=\"product-banner\"><div class=\"product-symbol\"><span>R5</span></div><div class=\"product-meta\"><div class=\"mini-label\">PILOT PRODUCT</div><h3>Busch R5 RA 0100 F</h3><p>Rotary-vane vacuum pump · source: prepared blueprint transcription</p></div><span class=\"signal-label\">EVIDENCE NOT INDEPENDENTLY VERIFIED</span></div>\n    <div class=\"stats\" id=\"stats\"><div class=\"stat\"><strong>16</strong><span>Proposed process requirements</span></div><div class=\"stat\"><strong>4</strong><span>Components assessed</span></div><div class=\"stat\"><strong>10</strong><span>Synthetic suppliers compared</span></div><div class=\"stat\"><strong>0</strong><span>Suppliers qualified</span></div></div>\n    <div class=\"columns-heading\"><div><h3>Component-to-process possibilities</h3><p>What processes could make the parts? Click a component to see proposed methods and supporting references.</p></div><span class=\"hint\">Open any card for details ↗</span></div>\n    <div class=\"component-grid\" id=\"component-grid\"><div class=\"loading-card\">Loading Patricio’s recorded pilot...</div></div>\n    <div class=\"columns-heading supplier-heading\"><div><h3>Supplier process compatibility</h3><p>These are <strong>synthetic</strong> supplier records. Color reflects whether a specific process was declared—not supplier suitability.</p></div><button type=\"button\" class=\"text-link\" data-panel=\"statusGuide\">Understand status labels <span>↗</span></button></div>\n    <div class=\"supplier-section\"><div class=\"legend\"><span class=\"legend-item\"><i class=\"key covered\"></i> Covered process</span><span class=\"legend-item\"><i class=\"key conditional\"></i> Conditional</span><span class=\"legend-item\"><i class=\"key general\"></i> Too general</span><span class=\"legend-item\"><i class=\"key missing\"></i> Not declared</span><span class=\"legend-item\"><i class=\"key skipped\"></i> Not compared</span></div><div id=\"supplier-list\" class=\"supplier-list\"><p class=\"loading-card\">Loading synthetic supplier results...</p></div></div>\n    <div class=\"callout\"><div><span class=\"callout-label\">READ THIS FIRST</span><p>“Process-compatible” is <strong>not</strong> the same as “able to manufacture the component.”</p></div><button class=\"outline-button\" type=\"button\" data-panel=\"difference\">See the difference <span>↗</span></button></div>\n  </section>\n\n  <section id=\"live\" class=\"section live\">\n    <div class=\"section-heading\"><div><p class=\"section-id\">02 / LIVE WEBSITE EXPERIMENT</p><h2>Try our working acquisition engine</h2><p class=\"subtitle\">Run our existing Pattern Systems → router → scraper on an approved site. Optionally use Cloudflare AI to propose source-quoted facts for review.</p></div><span class=\"live-status\"><i></i> LIVE CLOUDFlARE WORKER</span></div>\n    <div class=\"live-grid\">\n      <form id=\"live-form\" class=\"live-form\" autocomplete=\"off\">\n        <label for=\"site-select\">Approved website</label>\n        <select id=\"site-select\"><option value=\"https://www.saginawcontrol.com/\">Saginaw Control & Engineering</option><option value=\"https://www.dometic.com/\">Dometic</option></select>\n        <label for=\"token\">Scrapers API token <span>(presenter-only)</span></label>\n        <input id=\"token\" type=\"password\" autocomplete=\"off\" placeholder=\"Enter existing SCRAPPERS_API_TOKEN\" required>\n        <label class=\"switch-row\"><input type=\"checkbox\" id=\"ai-checkbox\"><span class=\"switch-ui\" aria-hidden=\"true\"></span><span><strong>Generate AI fact suggestions</strong><small>Optional Cloudflare Workers AI; may incur usage charges</small></span></label>\n        <button type=\"submit\" class=\"btn-primary run-button\" id=\"run-button\">Run investigation <span>↗</span></button>\n        <p class=\"form-foot\">Token stays in this request and is cleared from the field after submission. The app does not save credentials. The site allowlist and robots rules remain active.</p>\n      </form>\n      <div class=\"live-output\" id=\"live-output\" aria-live=\"polite\"><div class=\"empty-state\"><span class=\"outline-icon\">◇</span><h3>Ready for a live investigation</h3><p>Website results will appear here. The AI step only proposes facts supported by text quotes—it does not certify components or select suppliers.</p><button type=\"button\" data-panel=\"liveFlow\" class=\"text-link\">What exactly will run? ↗</button></div></div>\n    </div>\n  </section>\n\n  <section id=\"how\" class=\"section how\">\n    <div class=\"section-heading\"><div><p class=\"section-id\">03 / HOW THE SYSTEM FITS TOGETHER</p><h2>One story. Transparent decisions.</h2><p class=\"subtitle\">Click any step to see the technology, evidence rules, and what still needs to be built.</p></div></div>\n    <div class=\"flow-grid\">\n      <button type=\"button\" data-panel=\"acquisition\"><span>01 / WEBSITE</span><b>Detect + extract</b><small>Patterns, S01/S02/S03, evidence</small><i>VIEW DETAILS ↗</i></button>\n      <button type=\"button\" data-panel=\"aiFlow\"><span>02 / AI ASSISTANCE</span><b>Propose source facts</b><small>Cloudflare AI, quote-checked, review only</small><i>VIEW DETAILS ↗</i></button>\n      <button type=\"button\" data-panel=\"inference\"><span>03 / ENGINEERING</span><b>Infer processes</b><small>Patricio’s rules + ShopRadar codes</small><i>VIEW DETAILS ↗</i></button>\n      <button type=\"button\" data-panel=\"supplierFlow\"><span>04 / CAPABILITY</span><b>Match processes</b><small>Synthetic suppliers, no qualification</small><i>VIEW DETAILS ↗</i></button>\n    </div>\n    <div class=\"progress-note\"><strong>Next integration step</strong><p>Build a human-reviewed structured facts and component-role layer. Only approved records should feed Patricio’s deterministic process rules. Real supplier exports remain blocked by his existing safety policy.</p></div>\n  </section>\n  <footer class=\"footer\"><div><strong>PI</strong> / PRODUCT INSIGHTS — INSIDEJOB</div><p>Prototype demonstration · no production supplier decisions · all outcomes must be validated</p><a href=\"/health\" target=\"_blank\" rel=\"noopener noreferrer\">Technical health ↗</a></footer>\n</main>\n<div class=\"drawer-backdrop\" id=\"drawer-backdrop\" aria-hidden=\"true\"></div>\n<aside class=\"drawer\" id=\"detail-drawer\" role=\"dialog\" aria-modal=\"true\" aria-hidden=\"true\" aria-labelledby=\"drawer-title\">\n  <header class=\"drawer-head\"><div><p id=\"drawer-kicker\">DETAILS</p><h2 id=\"drawer-title\">Explanations</h2></div><button id=\"drawer-close\" class=\"close-button\" type=\"button\" aria-label=\"Close details\">×</button></header>\n  <div class=\"drawer-scroll\" id=\"drawer-body\"></div>\n  <div class=\"drawer-foot\"><span>Product Insights / Transparent reasoning</span><button class=\"text-link\" id=\"drawer-close-secondary\" type=\"button\">Close details ×</button></div>\n</aside>\n</body>\n</html>\n";
